type TaskSnapshot = {
  state: string;
  fields: Record<string, string>;
};

type FieldDefinition = {
  key: string;
  label: string;
  type: "text";
  required?: boolean;
  description?: string;
};

type WorkflowDecision =
  | { kind: "reject"; message: string }
  | { kind: "input-required"; fields: FieldDefinition[] }
  | { kind: "commit"; state: string; fields: Record<string, string> };

type CommandDefinition = {
  id: string;
  label: string;
  from?: string[];
  internalOnly?: boolean;
};

type ScheduleDefinition = {
  id: string;
  at: string;
  atKind?: "absolute" | "field";
  timezone?: string;
  dedupeKey: string;
  onFire: {
    type: "action";
    commandId: string;
    taskId?: string;
    input?: Record<string, string>;
  };
  missPolicy: "skip" | "run-once";
};

type UiSlotDefinition = {
  id: string;
  slot: "task.detail";
  title: string;
  body?: string;
  actions?: { commandId: string; label: string }[];
  fields?: { key: string; label: string }[];
  order?: number;
};

type Contribution = {
  fields?: FieldDefinition[];
  commands?: CommandDefinition[];
  schedules?: ScheduleDefinition[];
  uiSlots?: UiSlotDefinition[];
};

type DecideInput = {
  task: TaskSnapshot;
  action: string;
  input: Record<string, string>;
};

const dueAtField: FieldDefinition = {
  key: "dueAt",
  label: "截止时间",
  type: "text",
  description: "ISO 8601 时间，例如 2030-01-01T12:00:00Z；留空可清除",
};

const expiredField: FieldDefinition = {
  key: "expired",
  label: "已过期",
  type: "text",
};

function isLeapYear(year: number): boolean {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function daysInMonth(year: number, month: number): number {
  if (month === 2) return isLeapYear(year) ? 29 : 28;
  if (month === 4 || month === 6 || month === 9 || month === 11) return 30;
  return 31;
}

function isValidDueAt(value: string): boolean {
  const isoPattern =
    /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d{1,3})?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/i;
  if (!isoPattern.test(value)) return false;
  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));
  if (month < 1 || month > 12) return false;
  if (day < 1 || day > daysInMonth(year, month)) return false;
  return true;
}

export default {
  contribute(): Contribution {
    return {
      fields: [dueAtField, expiredField],
      commands: [
        { id: "setDue", label: "设截止", from: ["open", "done"] },
        { id: "expire", label: "标记过期", from: ["open"], internalOnly: true },
      ],
      schedules: [
        {
          id: "due-expire",
          atKind: "field",
          at: "dueAt",
          dedupeKey: "due-expire",
          onFire: { type: "action", commandId: "expire" },
          missPolicy: "run-once",
        },
      ],
      uiSlots: [
        {
          id: "due-detail",
          slot: "task.detail",
          title: "截止与过期",
          fields: [
            { key: "dueAt", label: "截止时间" },
            { key: "expired", label: "已过期" },
          ],
          actions: [{ commandId: "setDue", label: "设截止" }],
        },
      ],
    };
  },

  decide({ task, action, input }: DecideInput): WorkflowDecision {
    if (action === "setDue") {
      if (!Object.prototype.hasOwnProperty.call(input, "dueAt")) {
        return {
          kind: "input-required",
          fields: [{ ...dueAtField, required: false }],
        };
      }

      const dueAt = String(input["dueAt"]).trim();
      if (dueAt.length > 0 && !isValidDueAt(dueAt)) {
        return {
          kind: "reject",
          message:
            "请输入有效的 ISO 8601 截止时间，例如 2030-01-01T12:00:00Z；留空可清除",
        };
      }

      const fields: Record<string, string> = { ...task.fields };
      delete fields["expired"];
      if (dueAt.length > 0) fields["dueAt"] = dueAt;
      else delete fields["dueAt"];
      return { kind: "commit", state: task.state, fields };
    }

    if (action === "expire") {
      if (task.state !== "open") {
        return { kind: "reject", message: "仅未完成任务会自动标记过期" };
      }
      if (!task.fields["dueAt"]) {
        return { kind: "reject", message: "任务未设置截止时间" };
      }

      const scheduledAt =
        typeof input["scheduledAt"] === "string"
          ? input["scheduledAt"].trim()
          : "";
      if (task.fields["dueAt"] !== scheduledAt) {
        return { kind: "reject", message: "截止时间已修改或清除" };
      }

      return {
        kind: "commit",
        state: task.state,
        fields: { ...task.fields, expired: "true" },
      };
    }

    return { kind: "reject", message: "未知动作" };
  },
};

